// Generated by @dunx/create-app for dunx-boot. Yours to edit.
import { cp } from 'node:fs/promises'
import { depsPlugin } from '@dunx/transform'
import { join, resolve } from 'node:path'

const DIR = resolve(import.meta.dir, '..')
// Bun's compiler appends `.exe` on Windows, so the target name has to match.
const outfile = join(
  DIR,
  'dist',
  process.platform === 'win32' ? 'dunx-boot.exe' : 'dunx-boot'
)

const compiled = await Bun.build({
  entrypoints: [join(DIR, 'src/index.ts')],
  target: 'bun',
  // One self-contained executable: the Bun runtime plus the app in one file, so a
  // host needs nothing installed to run it.
  compile: { outfile },
  plugins: [depsPlugin],
  // Optional peers of @dunx/dashboard's queue board: the board lazily imports
  // them and falls back to a queue-less panel, so a host without them still
  // builds and runs.
  external: [
    '@bull-board/api',
    '@bull-board/api/bullMQAdapter',
    '@bull-board/bun',
    '@bull-board/ui',
  ],
  // Minification has been observed to break the compiled bundle's top-level
  // init on some modules; keep it off until the compiler handles it.
  minify: false,
  // A stack trace is never read off a shipped binary; symbols would only add size.
  sourcemap: 'none',
  tsconfig: join(DIR, 'tsconfig.json'),
})

if (!compiled.success) {
  for (const log of compiled.logs) console.error(log)
  throw new AggregateError(compiled.logs, 'compile failed')
}

const bytes = await Bun.file(outfile).bytes()

// The binary loads its config from `<cwd>/config`, so ship a copy next to it:
// `cd dist && ./dunx-boot` is then a complete deployment (run it from a
// directory without this app's bunfig.toml, which the binary no longer needs).
await cp(join(DIR, 'config'), join(DIR, 'dist', 'config'), { recursive: true })

console.log(
  `Built ${(bytes.byteLength / 1024 / 1024).toFixed(1)} MB -> ${outfile}`
)
